DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `generate_bus_seats_for_all_missing` ()   BEGIN
    DECLARE done INT DEFAULT 0;
    DECLARE v_bus_id BIGINT UNSIGNED;

    DECLARE cur CURSOR FOR
        SELECT b.id
        FROM buses b
        LEFT JOIN (
            SELECT bus_id, COUNT(*) AS seat_count
            FROM bus_seats
            GROUP BY bus_id
        ) s ON s.bus_id = b.id
        WHERE COALESCE(s.seat_count, 0) = 0;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    OPEN cur;

    read_loop: LOOP
        FETCH cur INTO v_bus_id;
        IF done = 1 THEN
            LEAVE read_loop;
        END IF;

        CALL generate_bus_seats_for_bus(v_bus_id);
    END LOOP;

    CLOSE cur;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `generate_bus_seats_for_bus` (IN `p_bus_id` BIGINT UNSIGNED)   BEGIN
    DECLARE v_layout VARCHAR(20);
    DECLARE v_total INT;
    DECLARE v_exists INT DEFAULT 0;

    SELECT layout_type, total_seats
    INTO v_layout, v_total
    FROM buses
    WHERE id = p_bus_id
    LIMIT 1;

    IF v_layout IS NULL OR v_total IS NULL OR v_total <= 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Invalid bus_id or bus has no total_seats';
    END IF;

    SELECT COUNT(*) INTO v_exists
    FROM bus_seats
    WHERE bus_id = p_bus_id;

    IF v_exists = 0 THEN

        -- 2x2 layout = 4 seats per row
        IF v_layout = '2x2' THEN
            INSERT INTO bus_seats
                (bus_id, seat_number, seat_type, row_no, col_no, is_active, created_at, updated_at)
            WITH RECURSIVE nums AS (
                SELECT 1 AS n
                UNION ALL
                SELECT n + 1 FROM nums WHERE n < v_total
            )
            SELECT
                p_bus_id AS bus_id,
                CONCAT(
                    FLOOR((n - 1) / 4) + 1,
                    CASE ((n - 1) % 4)
                        WHEN 0 THEN 'A'
                        WHEN 1 THEN 'B'
                        WHEN 2 THEN 'C'
                        WHEN 3 THEN 'D'
                    END
                ) AS seat_number,
                CASE
                    WHEN v_layout = 'sleeper' THEN 'sleeper'
                    WHEN v_layout = 'vip' THEN 'vip'
                    ELSE 'normal'
                END AS seat_type,
                FLOOR((n - 1) / 4) + 1 AS row_no,
                ((n - 1) % 4) + 1 AS col_no,
                1 AS is_active,
                NOW(),
                NOW()
            FROM nums;

        -- vip / 2x1 / sleeper / custom = 3 seats per row
        ELSE
            INSERT INTO bus_seats
                (bus_id, seat_number, seat_type, row_no, col_no, is_active, created_at, updated_at)
            WITH RECURSIVE nums AS (
                SELECT 1 AS n
                UNION ALL
                SELECT n + 1 FROM nums WHERE n < v_total
            )
            SELECT
                p_bus_id AS bus_id,
                CONCAT(
                    FLOOR((n - 1) / 3) + 1,
                    CASE ((n - 1) % 3)
                        WHEN 0 THEN 'A'
                        WHEN 1 THEN 'B'
                        WHEN 2 THEN 'C'
                    END
                ) AS seat_number,
                CASE
                    WHEN v_layout = 'sleeper' THEN 'sleeper'
                    WHEN v_layout IN ('vip', '2x1') THEN 'vip'
                    ELSE 'normal'
                END AS seat_type,
                FLOOR((n - 1) / 3) + 1 AS row_no,
                ((n - 1) % 3) + 1 AS col_no,
                1 AS is_active,
                NOW(),
                NOW()
            FROM nums;
        END IF;

    END IF;
END$$

DELIMITER ;

